<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><h1 class="h3 mb-4"><?= esc($title) ?></h1><div class="card border-0 p-4"><form method="post" action="<?= $admin ? site_url('admin/admin-users/'.$admin['id']) : site_url('admin/admin-users') ?>"><?= csrf_field() ?><?php if($admin): ?><input type="hidden" name="_method" value="PUT"><?php endif ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input class="form-control" name="name" value="<?= esc(old('name',$admin['name']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?= esc(old('email',$admin['email']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Mobile</label><input class="form-control" name="mobile" value="<?= esc(old('mobile',$admin['mobile']??'')) ?>"></div><div class="col-md-6"><label class="form-label">Role</label><select class="form-select" name="role_id" required><?php foreach($roles as $role): ?><option value="<?= esc($role['id']) ?>" <?= (string)old('role_id',$admin['role_id']??'')===(string)$role['id']?'selected':'' ?>><?= esc($role['name']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Password <?= $admin?'<span class="text-muted">(leave blank to keep)</span>':'' ?></label><input class="form-control" type="password" name="password" <?= $admin?'':'required' ?>></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active','inactive','blocked'] as $s): ?><option value="<?= $s ?>" <?= old('status',$admin['status']??'active')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></div></div><button class="btn btn-success mt-4">Save Admin</button></form></div><?= $this->endSection() ?>
